<div class="suki-assistant" data-shopping-assistant data-handoff-template="{{ url('/shopping-assistant/handoff/products/__product__') }}">
    <button type="button" data-assistant-launch class="suki-assistant-launch suki-btn suki-btn-primary shadow-lg" aria-expanded="false" aria-controls="shoppingAssistantPanel">
        <span class="grid h-5 w-5 place-items-center rounded bg-white/15 text-xs" aria-hidden="true">S</span><span>Ask SUKI</span>
    </button>
    <section id="shoppingAssistantPanel" data-assistant-panel hidden class="suki-assistant-panel" aria-label="SUKI shopping assistant" aria-live="polite">
        <header class="flex items-center justify-between gap-3 border-b border-[#d9e5da] px-4 py-3 text-[#173f35]"><div class="min-w-0"><strong class="block text-sm">SUKI Assistant</strong><p class="text-[11px] text-[#62786b]">Catalog and order support</p></div><div class="flex items-center gap-1"><button type="button" data-assistant-clear class="suki-btn suki-btn-ghost min-h-8 px-2 py-1 text-xs" aria-label="Clear assistant history" title="Clear history">Clear</button><button type="button" data-assistant-minimize class="suki-btn suki-btn-ghost suki-btn-icon min-h-8 w-8 p-0" aria-label="Minimize shopping assistant" title="Minimize shopping assistant" aria-pressed="false">−</button><button type="button" data-assistant-close class="suki-btn suki-btn-ghost suki-btn-icon min-h-8 w-8 p-0" aria-label="Close shopping assistant" title="Close shopping assistant">×</button></div></header>
        <div data-assistant-body class="flex min-h-0 flex-1 flex-col">
            <div data-assistant-log class="suki-assistant-log space-y-3 p-4 text-sm" role="log" aria-live="polite" aria-relevant="additions text"><p class="rounded-lg bg-[#eef5ed] p-3 text-[#234438]">Hi! Ask about products, COD, delivery, returns, or your order.</p></div>
            <div class="flex flex-wrap gap-2 px-4 pb-3" data-assistant-actions aria-label="Suggested questions">@foreach(['Find a product', 'Track my order', 'COD and delivery', 'Return or refund', 'Talk to support'] as $action)<button type="button" class="suki-btn suki-btn-outline min-h-8 px-2 py-1 text-xs">{{ $action }}</button>@endforeach</div>
            <form data-assistant-form class="flex gap-2 border-t border-[#d9e5da] p-3" action="{{ route('shopping-assistant.message') }}" method="POST">@csrf<label class="sr-only" for="shoppingAssistantInput">Ask SUKI</label><input id="shoppingAssistantInput" data-assistant-input maxlength="600" required class="suki-control min-w-0 flex-1 rounded-lg border border-[#bcd0c0] bg-white px-3 py-2 text-sm" placeholder="Ask about products or support"><button data-assistant-send class="suki-btn suki-btn-primary" type="submit">Send</button></form>
        </div>
    </section>
</div>
<script>
document.addEventListener('DOMContentLoaded', () => {
    const root = document.querySelector('[data-shopping-assistant]'); if (!root || root.dataset.initialized) return; root.dataset.initialized = 'true';
    const launch = root.querySelector('[data-assistant-launch]'), panel = root.querySelector('[data-assistant-panel]'), close = root.querySelector('[data-assistant-close]'), minimize = root.querySelector('[data-assistant-minimize]'), clear = root.querySelector('[data-assistant-clear]'), body = root.querySelector('[data-assistant-body]'), form = root.querySelector('[data-assistant-form]'), input = root.querySelector('[data-assistant-input]'), send = root.querySelector('[data-assistant-send]'), log = root.querySelector('[data-assistant-log]'), csrf = form.querySelector('[name=_token]')?.value;
    let prior = null, submitting = false;
    const setMinimized = (minimized) => { body.hidden = minimized; minimize.setAttribute('aria-pressed', String(minimized)); minimize.setAttribute('aria-label', minimized ? 'Expand shopping assistant' : 'Minimize shopping assistant'); minimize.title = minimized ? 'Expand shopping assistant' : 'Minimize shopping assistant'; minimize.textContent = minimized ? '+' : '−'; panel.classList.toggle('h-auto', minimized); };
    const open = () => { prior = document.activeElement; panel.hidden = false; launch.setAttribute('aria-expanded', 'true'); setMinimized(false); input.focus(); };
    const shut = () => { panel.hidden = true; launch.setAttribute('aria-expanded', 'false'); prior?.focus(); };
    const appendStatus = (text, style = '') => { const node = document.createElement('p'); node.className = `rounded-lg p-3 ${style}`.trim(); node.textContent = text; log.append(node); log.scrollTop = log.scrollHeight; return node; };
    const appendLink = (url, label) => { if (!url) return; const link = document.createElement('a'); link.href = url; link.className = 'mt-2 block rounded-lg border border-[#bfd2c2] p-2 text-xs font-semibold text-[#174f3f]'; link.textContent = label; log.append(link); };
    launch.addEventListener('click', open); close.addEventListener('click', shut); minimize.addEventListener('click', () => setMinimized(!body.hidden));
    clear.addEventListener('click', async () => { if (!csrf || clear.disabled) return; clear.disabled = true; try { const response = await fetch('{{ route('shopping-assistant.clear') }}', { method: 'POST', headers: { 'X-CSRF-TOKEN': csrf, 'Accept': 'application/json' } }); if (!response.ok) throw new Error('Unable to clear'); log.replaceChildren(); appendStatus('Conversation cleared. How can SUKI help?', 'bg-[#eef5ed] text-[#234438]'); } catch (_) { appendStatus('Unable to clear this conversation right now. Please try again.', 'border border-red-200 bg-red-50 text-red-700'); } finally { clear.disabled = false; } });
    document.addEventListener('keydown', event => { if (event.key === 'Escape' && !panel.hidden) shut(); });
    root.querySelectorAll('[data-assistant-actions] button').forEach(button => button.addEventListener('click', () => { input.value = button.textContent; form.requestSubmit(); }));
    form.addEventListener('submit', async event => { event.preventDefault(); const text = input.value.trim(); if (!text || submitting) return; submitting = true; send.disabled = true; send.textContent = 'Sending…'; appendStatus(text, 'border border-[#d9e5da] bg-white'); input.value = ''; const status = appendStatus('Looking that up…', 'text-[#62786b]'); try { const response = await fetch(form.action, { method: 'POST', headers: { 'X-CSRF-TOKEN': csrf, 'Accept': 'application/json', 'Content-Type': 'application/json' }, body: JSON.stringify({ message: text }) }); const data = await response.json(); status.textContent = data.text || data.message || 'I could not complete that request.'; (data.products || []).forEach(product => { appendLink(product.url, `${product.name} · ₱${Number(product.price).toFixed(2)}`); if (!product.id) return; const handoff = document.createElement('button'); handoff.type = 'button'; handoff.className = 'suki-btn suki-btn-ghost mt-1 min-h-7 px-0 py-0 text-xs underline'; handoff.textContent = 'Talk to this seller'; handoff.addEventListener('click', async () => { if (handoff.disabled) return; handoff.disabled = true; const confirmation = appendStatus('Open a human seller conversation for this product?', 'border border-[#bfd2c2] text-xs'); const cancel = document.createElement('button'), confirm = document.createElement('button'); cancel.type = confirm.type = 'button'; cancel.className = 'suki-btn suki-btn-ghost ml-2 min-h-7 px-1 py-0 text-xs underline'; confirm.className = 'suki-btn suki-btn-primary ml-2 min-h-7 px-2 py-1 text-xs'; cancel.textContent = 'Cancel'; confirm.textContent = 'Confirm'; cancel.addEventListener('click', () => { confirmation.remove(); handoff.disabled = false; }); confirm.addEventListener('click', async () => { confirm.disabled = true; try { const handoffResponse = await fetch(root.dataset.handoffTemplate.replace('__product__', product.id), { method: 'POST', headers: { 'X-CSRF-TOKEN': csrf, 'Accept': 'application/json', 'Content-Type': 'application/json' }, body: JSON.stringify({ confirm: true }) }); const result = await handoffResponse.json(); if (result.conversation_url) window.location.assign(result.conversation_url); else confirmation.textContent = result.message || 'Unable to open support right now.'; } catch (_) { confirmation.textContent = 'Unable to open support right now.'; } }); confirmation.append(cancel, confirm); }); log.append(handoff); }); appendLink(data.order_url, 'Open order tracking'); appendLink(data.support_url, 'Open Buyer Help'); } catch (_) { status.textContent = 'Support is temporarily unavailable. Please try again.'; status.className = 'rounded-lg border border-red-200 bg-red-50 p-3 text-red-700'; } finally { submitting = false; send.disabled = false; send.textContent = 'Send'; log.scrollTop = log.scrollHeight; } });
});
</script>
